// explorer.window: a live topic (snapshot-delta, latest).
// Generated by `pnpm nx g @app/generators:topic explorer.window`, then edited. Run
// `pnpm nx run contracts:api-docs` so the AsyncAPI document follows. An item never carries a
// write-only secret, and the ring is bounded by items and bytes (I-6).
//
// A grid shows at most 500 rows, so the subscription names them: `params.keys` are the keys on
// screen, from `inventory.query` rows. A change of what is visible is an `unsub` plus a `sub`
// (OQ-657). The topic publishes a row only when a sweep changed it, and only for those keys.
import { z } from 'zod';

import { ConnectionIdSchema } from '../brands.ts';
import { defineTopic } from '../kit/define-topic.ts';
import {
  ConnectionRowSchema,
  ExchangeRowSchema,
  QueueRowSchema,
  SWEPT_KINDS,
  VISIBLE_KEYS_MAX,
} from './explorer-types.ts';

/**
 * The reserved key of the version marker: an item with no `row`, published when a sweep added or
 * removed rows, so the grid refreshes its cache (OQ-658). An object key is base64url, so no row
 * can have this key.
 */
export const EXPLORER_VERSION_KEY = '~version';

export const ExplorerWindowParamsSchema = z.strictObject({
  cid: ConnectionIdSchema,
  /** The swept kinds only: bindings are per vhost and on demand, so no sweep installs them. */
  kind: z.enum(SWEPT_KINDS),
  /** The keys on screen. At most 500: the topic never follows a whole kind (I-7). */
  keys: z.array(z.string().max(1024)).max(VISIBLE_KEYS_MAX),
});

export const ExplorerWindowItemSchema = z.strictObject({
  /** The row key, or `~version` for the version marker. */
  key: z.string().max(1024),
  /** The index version this item is from. */
  version: z.number().int().nonnegative(),
  /**
   * The row as `inventory.query` returns it, without its `key` (the item carries it): the key is
   * about 700 bytes for a long name, and twice in an item it would not fit 500 rows in a frame.
   * Absent on the marker.
   */
  row: z
    .union([
      QueueRowSchema.omit({ key: true }),
      ExchangeRowSchema.omit({ key: true }),
      ConnectionRowSchema.omit({ key: true }),
    ])
    .optional(),
});

export const explorerWindowTopic = defineTopic({
  id: 'explorer.window',
  params: ExplorerWindowParamsSchema,
  item: ExplorerWindowItemSchema,
  qos: 'latest',
  flow: 'snapshot-delta',
  permission: 'broker.read',
  key: (item) => item.key,
  maxHz: 2,
  ring: { items: 1000, bytes: 1048576 },
});
